INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('guo-east','东虢国','["虢","东虢国"]',NULL,'cn','east_asia',-1046,1,NULL,'approximate_year',-767,12,NULL,'approximate_year',-12540,-9181,'ochre',NULL,NULL,'西周姬姓诸侯国，位于制邑（今河南荥阳一带）。通行说为周文王弟虢仲的封国，与西虢分别屏卫周王室。可考人物有虢仲、虢惠叔大林、虢叔旅及末君虢叔；惠叔与旅为父子，其余世系有断层。东、西虢始封君的归属存在异说。东虢为郑所灭，通行系年前767年；《左传》记末君虢叔死于制邑。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-east-dalin','大林','guo-east','["虢惠叔大林","惠叔大林"]','姬','虢',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','东虢君主，谥惠叔，虢叔旅之父。《虢叔旅钟》称“皇考惠叔大林”，记其侍奉周天子，旅作钟追念父亲。其与始封君虢仲之间的具体世系、生卒及在位起讫不详。','[{"label":"东虢国（始封与可考君主）","url":"https://zh.wikipedia.org/wiki/東虢國"},{"label":"何志華《西周金文韻讀研究淺議》（虢叔旅钟、惠叔大林父子）","url":"https://jas.hkbu.edu.hk/content/dam/jas-assets/publications/bulletin-of-the-jao-tsung-i-academy-of-sinology/issue-6-august-2019/12.pdf"},{"label":"虢仲（始封君归属异说及东虢世系待考区段）","url":"https://zh.wikipedia.org/wiki/虢仲"}]','惠叔',NULL,'虢惠叔','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-east-last-shu','？','guo-east','["东虢末君","东虢虢叔"]','姬','虢',NULL,NULL,NULL,NULL,-767,12,NULL,'approximate_year','["君主"]','东虢末代君主，史称虢叔，私名及父祖世系不详。《国语·郑语》记其与郑桓公同时；《左传·隐公元年》借郑庄公之言记“制，岩邑也，虢叔死焉”。东虢为郑所灭，通行系年为前767年；死亡方式未详。此人并非周文王之弟、西虢始封君虢叔。','[{"label":"《左传·隐公元年》（制邑、虢叔死焉）","url":"https://zh.wikisource.org/wiki/春秋左氏傳/隱公"},{"label":"《国语·郑语》（虢叔与郑桓公共时）","url":"https://ctext.org/guo-yu/zheng-yu/ens"},{"label":"孙尚勇《〈春秋〉历史叙事与孔子的文化关怀》（平王四年郑灭虢与杜预注）","url":"https://www.ica.org.cn/att/site17/20240529/1716968303123.pdf"},{"label":"东虢国（始封与可考君主）","url":"https://zh.wikipedia.org/wiki/東虢國"},{"label":"虢仲（始封君归属异说及东虢世系待考区段）","url":"https://zh.wikipedia.org/wiki/虢仲"}]',NULL,NULL,'虢叔','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-east-lv','旅','guo-east','["虢旅"]','姬','虢',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','虢惠叔大林之子，西周虢国君主，东虢君主名录所载。曾作虢叔旅钟追念亡父，铭文记其承继父德、侍奉天子；《秦志》将其审理鬲从与攸卫牧田邑争讼系于前847年。生卒与完整在位起讫不详。','[{"label":"东虢国（始封与可考君主）","url":"https://zh.wikipedia.org/wiki/東虢國"},{"label":"何志華《西周金文韻讀研究淺議》（虢叔旅钟、惠叔大林父子）","url":"https://jas.hkbu.edu.hk/content/dam/jas-assets/publications/bulletin-of-the-jao-tsung-i-academy-of-sinology/issue-6-august-2019/12.pdf"},{"label":"《陕西省志·秦志》大事年表（虢叔旅活动于前847年之说）","url":"https://dfz.shaanxi.gov.cn/zslm/fzzlk/xbsxsz/szdylpdf/201404/P020240923616206405975.pdf"},{"label":"虢仲（始封君归属异说及东虢世系待考区段）","url":"https://zh.wikipedia.org/wiki/虢仲"}]',NULL,NULL,'虢叔旅','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guo-east-zhong','仲','guo-east','[]','姬','虢',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','王季之子、周文王之弟，曾与虢叔同任文王卿士。周武王克商后分封二虢，通行说以虢仲封于制邑，为东虢始封君；东、西虢始封君的归属另有异说。生卒及具体在位起讫不详。','[{"label":"虢仲（始封君归属异说及东虢世系待考区段）","url":"https://zh.wikipedia.org/wiki/虢仲"},{"label":"东虢国（始封与可考君主）","url":"https://zh.wikipedia.org/wiki/東虢國"}]',NULL,NULL,'虢仲','[]');
